import type { Option } from '@/pdp/data/models';

export type BundleOptionQuantities = Record<string, number>;

export function readCanEditQuantity(value: Record<string, unknown>): boolean {
  return Boolean(value.canEditQuantity);
}

export function readDefaultOptionQuantity(
  value: Record<string, unknown>
): number {
  const raw = value.quantity ?? value.qty;
  const parsed = Number(raw);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 1;
}

export function buildBundleOptionQuantitiesFromOptions(
  options: Option[] | undefined,
  optionUIDs: string[] | undefined
): BundleOptionQuantities {
  if (!options?.length || !optionUIDs?.length) {
    return {};
  }

  const quantities: BundleOptionQuantities = {};

  for (const option of options) {
    if (option.typename !== 'ProductViewOptionValueProduct') {
      continue;
    }

    for (const item of option.items) {
      if (!optionUIDs.includes(item.id)) {
        continue;
      }

      quantities[item.id] = item.quantity ?? 1;
    }
  }

  return quantities;
}

export function mergeBundleOptionQuantities(
  previous: BundleOptionQuantities | undefined,
  options: Option[] | undefined,
  optionUIDs: string[] | undefined
): BundleOptionQuantities {
  const next = buildBundleOptionQuantitiesFromOptions(options, optionUIDs);

  if (!previous) {
    return next;
  }

  return Object.fromEntries(
    Object.entries(next).map(([uid, defaultQty]) => [
      uid,
      previous[uid] ?? defaultQty,
    ])
  );
}

export function bundleOptionQuantitiesToEnteredOptions(
  quantities: BundleOptionQuantities | undefined
): Array<{ uid: string; value: string }> {
  if (!quantities) {
    return [];
  }

  return Object.entries(quantities).map(([uid, quantity]) => ({
    uid,
    value: String(quantity),
  }));
}

export function bundleOptionQuantitiesFromEnteredOptions(
  enteredOptions: Array<{ uid: string; value: string }> | undefined
): BundleOptionQuantities {
  if (!enteredOptions?.length) {
    return {};
  }

  const quantities: BundleOptionQuantities = {};
  for (const option of enteredOptions) {
    const quantity = Number(option.value);
    if (Number.isFinite(quantity) && quantity > 0) {
      quantities[option.uid] = quantity;
    }
  }
  return quantities;
}
